const PROFILE_ASSETS = { 'generic-1u': 'rack-generic-1u.png', 'generic-2u': 'rack-generic-2u.png', 'unifi-switch-24': 'rack-unifi-switch-24.png', 'cisco-switch-24': 'rack-cisco-switch-24.png', 'switch-24': 'rack-switch-24.png', 'switch-48': 'rack-switch-48.png', router: 'rack-router.png', 'nas-2u': 'rack-nas-2u.png', 'ups-2u': 'rack-ups-2u.png', 'patch-panel-24': 'patch-panel-24.png', 'patch-panel-48': 'patch-panel-48.png', 'appliance-1u': 'rack-appliance-1u.png', 'server-1u': 'rack-generic-1u.png', 'server-2u': 'rack-generic-2u.png', firewall: 'rack-router.png', nas: 'rack-nas-2u.png', appliance: 'rack-appliance-1u.png' };
