  $('#discovery-list').innerHTML = discoveries.filter((item) => item.status === 'pending').length ? discoveries.filter((item) => item.status === 'pending').map((item) => `<div class="discovery-card"><div class="discovery-symbol">◎</div><div class="discovery-copy"><strong>${escapeHtml(item.hostname || item.ip)}</strong><small>${escapeHtml(item.ip)} · ${escapeHtml(item.role || 'Unknown device')} · ${escapeHtml((item.services || []).join(', ') || 'No recognised services')} · Ports: ${escapeHtml((item.ports || []).join(', ') || 'none')} · observed ${relativeTime(item.discoveredAt)}</small></div><button class="button secondary ignore-discovery" data-id="${item.id}">Ignore</button><button class="button secondary confirm-discovery" data-id="${item.id}">Confirm device</button></div>`).join('') : '<div class="empty">No pending discoveries. Run a scan when you are ready.</div>';
